The 99 Names of Allah
- #0 Best of Names 7:180; 20:8; 59:24
- #1 Ar-Rahman    ਬੇਅੰਤ ਰਹਿਮਤ ਵਾਲਾ (ਅਤਿ ਦਯਾਵਾਨ)  1:3; 17:110
- #2 Ar-Raheem     ਬੜਾ ਰਹਿਮ ਕਰਨ ਵਾਲਾ (ਅਤਿ ਕ੍ਰਿਪਾਲੂ)  2:163; 3:31; 4:100; 5:3
- #3 Al-Malik      ਬਾਦਸ਼ਾਹ, ਮਾਲਕ  20:114; 23:116; 59:23
- #4 Al-Quddus     ਪਵਿੱਤਰ (ਨਿਰਮਲ)  59:23; 62:1
- #5 As-Salaam     ਅਮਨ ਅਤੇ ਸ਼ਾਂਤੀ ਦਾ ਸਰੋਤ  59:23
- #6 Al-Mu'min     ਈਮਾਨ ਦੀ ਰਾਖੀ ਕਰਨ ਵਾਲਾ  59:23
- #7 Al-Muhaymin   ਰਾਖਾ, ਸੰਭਾਲ ਕਰਨ ਵਾਲਾ  59:23
- #8 Al-Aziz       ਬੜੇ ਇਕਤਿਆਰ ਵਾਲਾ, ਸ਼ਕਤੀਸ਼ਾਲੀ  3:6; 4:158; 9:40; 48:7
- #9 Al-Jabbar     ਜ਼ੋਰਾਵਰ, ਦਬਦਬਾ ਰੱਖਣ ਵਾਲਾ  59:23
- #10 Al-Mutakabbir ਵੱਡਿਆਈ ਵਾਲਾ, ਮਹਾਨ  59:23
- #11 Al-Khaliq    ਪੈਦਾ ਕਰਨ ਵਾਲਾ (ਸ੍ਰਿਸ਼ਟੀਕਰਤਾ)  6:102; 13:16; 39:62; 40:62; 59:24
- #12 Al-Bari'     ਅਸਤਿਤਵ ਵਿੱਚ ਲਿਆਉਣ ਵਾਲਾ  59:24
- #13 Al-Musawwir  ਸ਼ਕਲਾਂ ਬਣਾਉਣ ਵਾਲਾ  59:24
- #14 Al-Ghaffar   ਬੜਾ ਮੁਆਫ਼ ਕਰਨ ਵਾਲਾ, ਖ਼ਤਾ ਢੱਕਣ ਵਾਲਾ  20:82; 38:66; 39:5; 40:42; 71:10
- #15 Al-Qahhar    ਸਭ ਉੱਤੇ ਗ਼ਾਲਬ, ਕਾਬੂ ਰੱਖਣ ਵਾਲਾ  13:16; 14:48; 38:65; 39:4; 40:16
- #16 Al-Wahhab    ਬੜਾ ਦਾਤਾ, ਬਖ਼ਸ਼ਿਸ਼ ਕਰਨ ਵਾਲਾ  3:8; 38:9; 38:35
- #17 Ar-Razzaq    ਰੋਜ਼ੀ ਦੇਣ ਵਾਲਾ, ਰਾਜ਼ਕ  51:58
- #18 Al-Fattah    ਖੋਲ੍ਹਣ ਵਾਲਾ, ਮੁਸ਼ਕਲਾਂ ਸੁਲਝਾਉਣ ਵਾਲਾ  34:26
- #19 Al-Aleem     ਸਭ ਕੁਝ ਜਾਣਨ ਵਾਲਾ  2:158; 3:92; 4:35; 24:41; 33:40
- #20 Al-Qabid     ਤੰਗ ਕਰਨ ਵਾਲਾ, ਰੋਕਣ ਵਾਲਾ  2:245
- #21 Al-Basit     ਵਿਸਥਾਰ ਦੇਣ ਵਾਲਾ, ਖੋਲ੍ਹਣ ਵਾਲਾ  2:245
- #22 Al-Khafid    ਨੀਵਾਂ ਕਰਨ ਵਾਲਾ, ਪਸਤ ਕਰਨ ਵਾਲਾ  95:5
- #23 Ar-Rafi'     ਉੱਚਾ ਕਰਨ ਵਾਲਾ, ਬੁਲੰਦੀਆਂ ਬਖ਼ਸ਼ਣ ਵਾਲਾ  58:11; 6:83
- #24 Al-Mu'izz    ਇੱਜ਼ਤ ਦੇਣ ਵਾਲਾ  3:26
- #25 Al-Mudhill   ਜ਼ਿਲਤ ਦੇਣ ਵਾਲਾ, ਥੱਲੇ ਪਾਉਣ ਵਾਲਾ  3:26
- #26 As-Sami'     ਸਭ ਸੁਣਨ ਵਾਲਾ  2:127; 2:256; 8:17; 49:1
- #27 Al-Basir     ਸਭ ਵੇਖਣ ਵਾਲਾ  4:58; 17:1; 42:11; 42:27
- #28 Al-Hakam     ਇਨਸਾਫ਼ ਕਰਨ ਵਾਲਾ, ਫ਼ੈਸਲਾ ਕਰਨ ਵਾਲਾ  22:69
- #29 Al-Adl       ਅਦਲ ਕਰਨ ਵਾਲਾ, ਨਿਆਂ ਕਰਨ ਵਾਲਾ  6:115
- #30 Al-Latif     ਬੜਾ ਲਤੀਫ਼, ਕਿਰਪਾਲੂ  6:103; 22:63; 31:16; 33:34
- #31 Al-Khabir    ਖਬਰ ਰੱਖਣ ਵਾਲਾ, ਸੂਝਵਾਨ  6:18; 17:30; 49:13; 59:18
- #32 Al-Halim     ਬੜਾ ਬਰਦਾਸ਼ਤ ਕਰਨ ਵਾਲਾ, ਸਹਿਣਸ਼ੀਲ  2:235; 17:44; 22:59; 35:41
- #33 Al-Azim      ਬੜੀ ਵੱਡਿਆਈ ਵਾਲਾ, ਮਹਾਨ  2:255; 42:4; 56:96
- #34 Al-Ghafur    ਬੜਾ ਮੁਆਫ਼ ਕਰਨ ਵਾਲਾ, ਗ਼ਫ਼ੂਰ  2:173; 8:69; 16:110; 41:32
- #35 Ash-Shakur   ਕਦਰ ਕਰਨ ਵਾਲਾ, ਸ਼ੁਕਰਗੁਜ਼ਾਰ  35:30; 35:34; 42:23; 64:17
- #36 Al-Aliy      ਬੜੀਆਂ ਉੱਚਾਈਆਂ ਵਾਲਾ, ਬੁਲੰਦ  4:34; 31:30; 42:4; 42:51
- #37 Al-Kabir     ਬੜਾ ਵੱਡਾ, ਮਹਾਨ  13:9; 22:62; 31:30
- #38 Al-Hafiz     ਸਭ ਦਾ ਰਾਖਾ, ਸਾਂਭ ਸੰਭਾਲ ਕਰਨ ਵਾਲਾ  11:57; 34:21; 42:6
