Matching Ayahs
- = ਅਲਿਫ਼, ਲਾਮ, ਮੀਮ। 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = ਇਹ ਲੋਕ ਆਪਣੇ ਰੱਬ ਵੱਲੋਂ ਸਿੱਧੇ ਰਾਹ 'ਤੇ ਹਨ, ਅਤੇ ਇਹੀ ਲੋਕ ਸਫ਼ਲ ਹੋਣ ਵਾਲੇ ਹਨ। 2:5; 31:5
- = ਐ ਬਨੀ ਇਸਰਾਈਲ! ਮੇਰੀ ਉਹ ਨੇ'ਮਤ ਯਾਦ ਕਰੋ ਜੋ ਮੈਂ ਤੁਹਾਡੇ 'ਤੇ ਕੀਤੀ ਅਤੇ ਮੈਂ ਤੁਹਾਨੂੰ ਸਾਰੇ ਜਗਤਾਂ (ਲੋਕਾਂ) ਉੱਤੇ ਉੱਤਮਤਾ ਦਿੱਤੀ। 2:47; 2:122
- = ਉਹ ਇੱਕ ਉਮੱਤ ਸੀ ਜੋ ਲੰਘ ਗਈ। ਉਹਨਾਂ ਨੂੰ ਉਹਨਾਂ ਦੀ ਕਮਾਈ ਦਾ ਫਲ ਹੈ, ਅਤੇ ਤੁਹਾਨੂੰ ਤੁਹਾਡੀ ਕਮਾਈ ਦਾ। ਅਤੇ ਤੁਹਾਨੂੰ ਉਹਨਾਂ ਦੇ ਕਰਮਾਂ ਬਾਰੇ ਨਹੀਂ ਪੁੱਛਿਆ ਜਾਵੇਗਾ। 2:134; 2:141
- = ਉਹ ਉਸ ਵਿੱਚ ਹਮੇਸ਼ਾ ਰਹਿਣਗੇ। ਉਹਨਾਂ ਦੀ ਸਜਾ ਹੌਲੀ ਨਹੀਂ ਕੀਤੀ ਜਾਵੇਗੀ ਅਤੇ ਨਾ ਹੀ ਉਹਨਾਂ ਨੂੰ ਮੌਹਲਤ ਦਿੱਤੀ ਜਾਵੇਗੀ। 2:162; 3:88
- = ਪਰ ਜਿਹੜੇ ਇਸ ਤੋਂ ਬਾਅਦ ਤੌਬਾ ਕਰਨ ਅਤੇ ਆਪਣੇ ਆਪ ਨੂੰ ਸੁਧਾਰ ਲੈਣ। ਨਿਸ਼ਚੇ ਹੀ ਅੱਲਾਹ ਮਾਫ਼ ਕਰਨ ਵਾਲਾ, ਬਹੁਤ ਦਯਾਵਾਨ ਹੈ। 3:89; 24:5
- = ਅਤੇ ਜਿਨ੍ਹਾਂ ਨੇ ਇਨਕਾਰ ਕੀਤਾ ਅਤੇ ਸਾਡੀਆਂ ਆਇਤਾਂ ਨੂੰ ਝੁਠਲਾਇਆ – ਉਹੀ ਲੋਕ ਜਹੰਨਮ ਦੇ ਰਹਿਣ ਵਾਲੇ ਹਨ। 5:10; 5:86
- = ਅਤੇ ਉਹਨਾਂ ਦੇ ਰੱਬ ਦੀਆਂ ਨਿਸ਼ਾਨੀਆਂ ਵਿੱਚੋਂ ਜਦੋਂ ਵੀ ਕੋਈ ਨਿਸ਼ਾਨੀ ਉਹਨਾਂ ਕੋਲ ਆਉਂਦੀ ਹੈ, ਉਹ ਉਸ ਤੋਂ ਮੂੰਹ ਮੋੜ ਲੈਂਦੇ ਹਨ। 6:4; 36:46
- = ਅਤੇ ਤੁਹਾਡੇ ਤੋਂ ਪਹਿਲਾਂ ਵੀ ਰਸੂਲਾਂ ਦਾ ਮਖੌਲ ਉਡਾਇਆ ਗਿਆ, ਪਰ ਜਿਨ੍ਹਾਂ ਨੇ ਮਖੌਲ ਕੀਤਾ, ਉਹਨਾਂ ਨੂੰ ਉਸੇ ਚੀਜ਼ ਨੇ ਘੇਰ ਲਿਆ ਜਿਸ ਦਾ ਉਹ ਮਖੌਲ ਕਰ ਰਹੇ ਸਨ। 6:10; 21:41
- = ਆਖ ਦਿਓ: "ਜੇਕਰ ਮੈਂ ਆਪਣੇ ਰੱਬ ਦੀ ਨਾਫ਼ਰਮਾਨੀ ਕਰਾਂ, ਤਾਂ ਮੈਂ ਵੱਡੇ ਦਿਨ ਦੀ ਸਜਾ ਤੋਂ ਡਰਦਾ ਹਾਂ।" 6:15; 39:13
- = ਫਿਰ ਭੁਚਾਲ ਨੇ ਉਹਨਾਂ ਨੂੰ ਫੜ ਲਿਆ, ਅਤੇ ਉਹ ਆਪਣੇ ਘਰਾਂ ਵਿੱਚ ਉਲਥੇ ਪੈ ਗਏ। 7:78; 7:91
- = ਫਿਰ ਉਸ ਨੇ ਆਪਣੀ ਲਾਠੀ ਸੁੱਟੀ, ਅਤੇ ਉਹ ਤੁਰੰਤ ਇੱਕ ਸਪੱਸ਼ਟ ਸੱਪ ਬਣ ਗਈ। 7:107; 26:32
- = ਅਤੇ ਉਸ ਨੇ ਆਪਣਾ ਹੱਥ ਕੱਢਿਆ, ਤਾਂ ਉਹ ਵੇਖਣ ਵਾਲਿਆਂ ਲਈ ਚਮਕੀਲਾ ਚਿੱਟਾ ਸੀ। 7:108; 26:33
- = ਉਹਨਾਂ ਨੇ ਆਖਿਆ: "ਅਸੀਂ ਸਾਰੇ ਸੰਸਾਰ ਦੇ ਰੱਬ ਉੱਤੇ ਈਮਾਨ ਲਿਆਏ।" 7:121; 26:47
- = ਮੂਸਾ ਅਤੇ ਹਾਰੂਨ ਦਾ ਰੱਬ। 7:122; 26:48
- = ਅਤੇ ਮੈਂ ਉਹਨਾਂ ਨੂੰ ਮੌਹਲਤ ਦੇਵਾਂਗਾ। ਨਿਸ਼ਚੇ ਹੀ ਮੇਰੀ ਯੋਜਨਾ ਮਜ਼ਬੂਤ ਹੈ। 7:183; 68:45
- = ਉਹੀ ਹੈ ਜਿਸ ਨੇ ਆਪਣੇ ਰਸੂਲ ਨੂੰ ਸਿੱਧਾ ਰਾਹ ਅਤੇ ਸੱਚੇ ਧਰਮ ਦੇ ਨਾਲ ਭੇਜਿਆ, ਤਾਂ ਜੋ ਉਸ ਨੂੰ ਸਾਰੇ ਧਰਮਾਂ ਉੱਤੇ ਗ਼ਾਲਿਬ ਕਰ ਦੇਵੇ, ਭਾਵੇਂ ਮੁਸ਼ਰਿਕਾਂ ਨੂੰ ਬੁਰਾ ਲੱਗੇ। 9:33; 61:9
- = ਐ ਨਬੀ! ਕਾਫ਼ਰਾਂ ਅਤੇ ਮੁਨਾਫ਼ਿਕਾਂ ਨਾਲ ਜਿਹਾਦ ਕਰੋ ਅਤੇ ਉਹਨਾਂ 'ਤੇ ਸਖ਼ਤੀ ਕਰੋ। ਉਹਨਾਂ ਦਾ ਟਿਕਾਣਾ ਜਹੰਨਮ ਹੈ, ਅਤੇ ਉਹ ਕਿੰਨਾ ਬੁਰਾ ਟਿਕਾਣਾ ਹੈ! 9:73; 66:9
- = ਅਤੇ ਉਹ ਆਖਦੇ ਹਨ: "ਇਹ ਵਾਅਦਾ ਕਦੋਂ ਪੂਰਾ ਹੋਵੇਗਾ, ਜੇਕਰ ਤੁਸੀਂ ਸੱਚੇ ਹੋ?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = ਅਤੇ ਅਸੀਂ ਮੂਸਾ ਨੂੰ ਆਪਣੀਆਂ ਨਿਸ਼ਾਨੀਆਂ ਅਤੇ ਸਪੱਸ਼ਟ ਹੁਕਮ ਦੇ ਨਾਲ ਭੇਜਿਆ। 11:96; 40:23
- = ਅਤੇ ਅਸੀਂ ਮੂਸਾ ਨੂੰ ਕਿਤਾਬ ਦਿੱਤੀ, ਪਰ ਉਸ ਵਿੱਚ ਮੱਤਭੇਦ ਪੈਦਾ ਹੋ ਗਿਆ। ਅਤੇ ਜੇਕਰ ਤੁਹਾਡੇ ਰੱਬ ਵੱਲੋਂ ਇੱਕ ਪਹਿਲੀ ਗੱਲ ਨਾ ਹੁੰਦੀ, ਤਾਂ ਉਹਨਾਂ ਵਿੱਚ ਫੈਸਲਾ ਕਰ ਦਿੱਤਾ ਜਾਂਦਾ। ਅਤੇ ਨਿਸ਼ਚੇ ਹੀ ਉਹ ਇਸ ਬਾਰੇ ਸ਼ੱਕ ਵਿੱਚ ਹਨ। 11:110; 41:45
- = ਇਹ ਅੱਲਾਹ ਲਈ ਔਖਾ ਨਹੀਂ। 14:20; 35:17
- = "ਜਦੋਂ ਮੈਂ ਉਸ ਨੂੰ ਠੀਕ-ਠਾਕ ਕਰ ਦਿਆਂਗਾ ਅਤੇ ਉਸ ਵਿੱਚ ਆਪਣੀ ਰੂਹ ਫੂਕ ਦਿਆਂਗਾ, ਤਾਂ ਤੁਸੀਂ ਉਸ ਅੱਗੇ ਸਜਦੇ ਵਿੱਚ ਡਿੱਗ ਪਓ।" 15:29; 38:72
- = ਫਿਰ ਸਾਰੇ ਫ਼ਰਿਸ਼ਤਿਆਂ ਨੇ ਸਜਦਾ ਕੀਤਾ। 15:30; 38:73
- = (ਅੱਲਾਹ ਨੇ) ਆਖਿਆ: "ਤਾਂ ਤੂੰ ਉਸ ਵਿੱਚੋਂ ਨਿਕਲ ਜਾ, ਕਿਉਂਕਿ ਤੂੰ ਰੱਦ ਕੀਤਾ ਹੋਇਆ ਹੈਂ।" 15:34; 38:77
- = (ਇਬਲੀਸ ਨੇ) ਆਖਿਆ: "ਮੇਰੇ ਰੱਬ! ਤਾਂ ਮੈਨੂੰ ਉਸ ਦਿਨ ਤੱਕ ਮੌਹਲਤ ਦੇਵੀਂ, ਜਦੋਂ ਉਹ ਦੁਬਾਰਾ ਉਠਾਏ ਜਾਣਗੇ।" 15:36; 38:79
- = (ਅੱਲਾਹ ਨੇ) ਆਖਿਆ: "ਤਾਂ ਨਿਸ਼ਚੇ ਹੀ ਤੂੰ ਮੌਹਲਤ ਦਿੱਤੇ ਗਏ ਲੋਕਾਂ ਵਿੱਚੋਂ ਹੈਂ।" 15:37; 38:80
- = ਇੱਕ ਨਿਸ਼ਚਿਤ ਸਮੇਂ ਦੇ ਦਿਨ ਤੱਕ।" 15:38; 38:81
- = ਉਹਨਾਂ ਵਿੱਚੋਂ ਤੇਰੇ ਚੁਣੇ ਹੋਏ ਬੰਦਿਆਂ ਤੋਂ ਬਿਨਾਂ। 15:40; 38:83
- = ਨਿਸ਼ਚੇ ਹੀ ਪਰਹੇਜ਼ਗਾਰ ਲੋਕ ਬਾਗਾਂ ਅਤੇ ਚਸ਼ਮਿਆਂ ਵਿੱਚ ਹੋਣਗੇ। 15:45; 51:15
- = (ਇਬਰਾਹੀਮ ਨੇ) ਆਖਿਆ: "ਤਾਂ ਤੁਹਾਡਾ ਕੀ ਕੰਮ ਹੈ, ਐ ਰਸੂਲੋ?" 15:57; 51:31
- = ਉਹਨਾਂ ਨੇ ਆਖਿਆ: "ਅਸੀਂ ਇੱਕ ਅਪਰਾਧੀ ਕੌਮ ਵੱਲ ਭੇਜੇ ਗਏ ਹਾਂ।" 15:58; 51:32
- = ਜਿਹੜੇ ਈਮਾਨ ਲਿਆਉਂਦੇ ਹਨ ਅਤੇ ਆਪਣੇ ਈਮਾਨ ਨੂੰ ਜ਼ੁਲਮ ਨਾਲ ਨਹੀਂ ਮਿਲਾਉਂਦੇ – ਉਹਨਾਂ ਲਈ ਸੁਰੱਖਿਆ ਹੈ ਅਤੇ ਉਹੀ ਸਿੱਧੀ ਰਾਹ 'ਤੇ ਹਨ। 16:42; 29:59
- = ਤਾਂ ਕਿ ਉਹ ਸਾਡੀ ਦਿੱਤੀ ਹੋਈ ਚੀਜ਼ ਦਾ ਇਨਕਾਰ ਕਰਨ। ਤਾਂ ਤੁਸੀਂ ਆਨੰਦ ਲਵੋ, ਕਿਉਂਕਿ ਛੇਤੀ ਹੀ ਤੁਹਾਨੂੰ ਪਤਾ ਲੱਗ ਜਾਵੇਗਾ। 16:55; 30:34
- = ਫਿਰ ਉਸ (ਜ਼ੁਲਕਰਨੈਨ) ਨੇ ਇੱਕ ਰਾਹ ਫੜਿਆ। 18:89; 18:92
- = ਫ਼ਿਰਔਨ ਕੋਲ ਜਾ, ਕਿਉਂਕਿ ਉਸ ਨੇ ਬਹੁਤ ਉਲੰਘਣਾ ਕੀਤੀ ਹੈ। 20:24; 79:17
- = ਅਤੇ ਜਿਹੜੇ ਆਪਣੀਆਂ ਸ਼ਰਮਗਾਹਾਂ ਦੀ ਰਾਖੀ ਕਰਦੇ ਹਨ। 23:5; 70:29
- = ਆਪਣੀਆਂ ਪਤਨੀਆਂ ਜਾਂ ਆਪਣੇ ਸੱਜੇ ਹੱਥਾਂ ਦੀ ਮਲਕੀਅਤ (ਦਾਸੀਆਂ) ਤੋਂ ਇਲਾਵਾ – ਕਿਉਂਕਿ ਉਹਨਾਂ ਨੂੰ ਕੋਈ ਮਲਾਮਤ ਨਹੀਂ। 23:6; 70:30
- = ਪਰ ਜਿਹੜੇ ਇਸ ਤੋਂ ਬਾਅਦ ਇੱਛਾ ਕਰਨ – ਉਹੀ ਲੋਕ ਹੱਦ ਤੋਂ ਵੱਧ ਜਾਣ ਵਾਲੇ ਹਨ। 23:7; 70:31
- = ਅਤੇ ਜਿਹੜੇ ਆਪਣੀਆਂ ਅਮਾਨਤਾਂ ਅਤੇ ਆਪਣੇ ਇਕਰਾਰਾਂ ਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹਨ। 23:8; 70:32
- = (ਨੂਹ ਨੇ) ਆਖਿਆ: "ਮੇਰੇ ਰੱਬ! ਮੇਰੀ ਮਦਦ ਕਰ, ਕਿਉਂਕਿ ਉਹਨਾਂ ਨੇ ਮੈਨੂੰ ਝੁਠਲਾਇਆ ਹੈ।" 23:26; 23:39
- = ਤਾ, ਸੀਨ, ਮੀਮ। 26:1; 28:1
- = ਇਹ ਸਪਸ਼ਟ ਕਿਤਾਬ ਦੀਆਂ ਆਇਤਾਂ ਹਨ। 26:2; 28:2
- = ਨਿਸ਼ਚੇ ਹੀ ਇਸ ਵਿੱਚ ਇੱਕ ਨਿਸ਼ਾਨੀ ਹੈ, ਪਰ ਉਹਨਾਂ ਵਿੱਚੋਂ ਬਹੁਤੇ ਈਮਾਨ ਲਿਆਉਣ ਵਾਲੇ ਨਹੀਂ। 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = ਅਤੇ ਨਿਸ਼ਚੇ ਹੀ ਤੁਹਾਡਾ ਰੱਬ – ਉਹੀ ਉੱਤਮ ਸ਼ਕਤੀ ਵਾਲਾ, ਬਹੁਤ ਰਹਿਮ ਵਾਲਾ ਹੈ। 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = ਅਤੇ ਅਸੀਂ ਬਾਕੀ ਲੋਕਾਂ ਨੂੰ ਡੁਬੋ ਦਿੱਤਾ। 26:66; 37:82
- = ਨਿਸ਼ਚੇ ਹੀ ਮੈਂ ਤੁਹਾਡੇ ਲਈ ਇੱਕ ਅਮਾਨਤਦਾਰ ਰਸੂਲ ਹਾਂ। 26:107; 26:125; 26:143; 26:162; 26:178
- = ਤਾਂ ਅੱਲਾਹ ਤੋਂ ਡਰੋ ਅਤੇ ਮੇਰੀ ਗੱਲ ਮੰਨੋ। 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = ਅਤੇ ਮੈਂ ਇਸ ਉੱਤੇ ਤੁਹਾਡੇ ਤੋਂ ਕੋਈ ਬਦਲਾ ਨਹੀਂ ਮੰਗਦਾ; ਮੇਰਾ ਬਦਲਾ ਤਾਂ ਸਾਰੇ ਸੰਸਾਰ ਦੇ ਰੱਬ ਦੇ ਕੋਲ ਹੈ। 26:109; 26:127; 26:145; 26:164; 26:180
- = ਬਾਗਾਂ ਅਤੇ ਚਸ਼ਮਿਆਂ ਵਿੱਚ। 26:147; 44:52
- = ਉਹਨਾਂ ਨੇ ਆਖਿਆ: "ਤੂੰ ਤਾਂ ਜਾਦੂ ਕੀਤੇ ਗਏ ਲੋਕਾਂ ਵਿੱਚੋਂ ਹੈਂ।" 26:153; 26:185
- = ਉਸ ਦੀ ਪਤਨੀ ਨੂੰ ਛੱਡ ਕੇ – ਅਸੀਂ ਪਹਿਲਾਂ ਹੀ ਫੈਸਲਾ ਕਰ ਚੁੱਕੇ ਸੀ ਕਿ ਉਹ ਪਿੱਛੇ ਰਹਿ ਜਾਣ ਵਾਲਿਆਂ ਵਿੱਚੋਂ ਹੋਵੇਗੀ। 26:171; 37:135
- = ਫਿਰ ਅਸੀਂ ਬਾਕੀ ਲੋਕਾਂ ਨੂੰ ਤਬਾਹ ਕਰ ਦਿੱਤਾ। 26:172; 37:136
- = ਅਤੇ ਅਸੀਂ ਉਹਨਾਂ ਉੱਤੇ (ਪੱਥਰਾਂ ਦੀ) ਵਰਖਾ ਕੀਤੀ, ਅਤੇ ਡਰਾਏ ਗਏ ਲੋਕਾਂ ਉੱਤੇ ਮੀਂਹ ਕਿੰਨਾ ਬੁਰਾ ਸੀ! 26:173; 27:58
- = ਤਾਂ ਕੀ ਉਹ ਸਜਾ ਦੀ ਜਲਦੀ ਕਰ ਰਹੇ ਹਨ? 26:204; 37:176
- = ਜਿਹੜੇ ਨਮਾਜ਼ ਕਾਇਮ ਕਰਦੇ ਹਨ, ਜ਼ਕਾਤ ਦਿੰਦੇ ਹਨ ਅਤੇ ਆਖ਼ਿਰਤ ਉੱਤੇ ਵਿਸ਼ਵਾਸ ਰੱਖਦੇ ਹਨ। 27:3; 31:4
- = ਅਤੇ (ਯਾਦ ਕਰੋ) ਉਸ ਦਿਨ ਨੂੰ ਜਦੋਂ ਉਹ ਉਹਨਾਂ ਨੂੰ ਆਵਾਜ਼ ਦੇਵੇਗਾ ਅਤੇ ਆਖੇਗਾ: "ਮੇਰੇ ਉਹ ਭਾਈਵਾਲ ਕਿੱਥੇ ਹਨ ਜਿਨ੍ਹਾਂ ਨੂੰ ਤੁਸੀਂ (ਝੂਠ) ਆਖਦੇ ਸੀ?" 28:62; 28:74
- = ਅਤੇ ਸਾਡੇ ਪੁਰਖੇ? 37:17; 56:48
- = ਅਤੇ ਉਹ ਇੱਕ ਦੂਜੇ ਵੱਲ ਮੁੜਨਗੇ ਅਤੇ ਇੱਕ ਦੂਜੇ ਨੂੰ ਪੁੱਛਣਗੇ। 37:27; 52:25
- = ਪਰ (ਉਹ) ਅੱਲਾਹ ਦੇ ਚੁਣੇ ਹੋਏ ਬੰਦੇ ਹਨ। 37:40; 37:74; 37:128; 37:160
- = ਨੇ'ਮਤਾਂ ਦੇ ਬਾਗਾਂ ਵਿੱਚ। 37:43; 56:12
- = ਅਤੇ ਅਸੀਂ ਉਸ ਲਈ ਬਾਅਦ ਵਾਲਿਆਂ ਵਿੱਚ (ਚੰਗਾ ਨਾਮ) ਛੱਡਿਆ: 37:78; 37:108; 37:129
- = ਨਿਸ਼ਚੇ ਹੀ ਅਸੀਂ ਨੇਕੀ ਕਰਨ ਵਾਲਿਆਂ ਨੂੰ ਇਸੇ ਤਰ੍ਹਾਂ ਬਦਲਾ ਦਿੰਦੇ ਹਾਂ। 37:80; 37:121; 37:131; 77:44
- = ਨਿਸ਼ਚੇ ਹੀ ਉਹ ਸਾਡੇ ਈਮਾਨਦਾਰ ਬੰਦਿਆਂ ਵਿੱਚੋਂ ਸੀ। 37:81; 37:111; 37:132
- = ਤੁਹਾਨੂੰ ਕੀ ਹੋ ਗਿਆ ਹੈ? ਕਿਵੇਂ ਫੈਸਲਾ ਕਰ ਰਹੇ ਹੋ? 37:154; 68:36
- = ਇਹ (ਕੁਰਆਨ) ਸਾਰੇ ਸੰਸਾਰ ਲਈ ਇੱਕ ਉਪਦੇਸ਼ ਹੈ। 38:87; 81:27
- = ਇਸ ਕਿਤਾਬ ਦਾ ਉਤਰਨਾ ਅੱਲਾਹ ਵੱਲੋਂ ਹੈ – ਉੱਤਮ ਸ਼ਕਤੀ ਵਾਲਾ, ਬੜੀ ਹਿਕਮਤ ਵਾਲਾ। 39:1; 45:2; 46:2
- = ਹਾ, ਮੀਮ। 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = ਸਪਸ਼ਟ ਕਿਤਾਬ ਦੀ ਸੌਂਹ। 43:2; 44:2
- = ਤਾਂ ਤੁਸੀਂ ਉਹਨਾਂ ਨੂੰ ਛੱਡ ਦਿਓ – ਉਹ ਬੇਕਾਰ ਗੱਲਾਂ ਅਤੇ ਖੇਡ-ਕੁੱਦ ਵਿੱਚ ਮਸਤ ਰਹਿਣ, ਜਦੋਂ ਤੱਕ ਉਹ ਆਪਣੇ ਉਸ ਦਿਨ ਨੂੰ ਨਾ ਮਿਲਣ ਜਿਸ ਦਾ ਉਹਨਾਂ ਨੂੰ ਵਾਅਦਾ ਕੀਤਾ ਗਿਆ ਹੈ। 43:83; 70:42
- = (ਉਹਨਾਂ ਨੂੰ ਆਖਿਆ ਜਾਵੇਗਾ): "ਤੁਸੀਂ ਜੋ ਕੁਝ ਕਰਦੇ ਸੀ, ਉਸ ਦੇ ਬਦਲੇ ਆਨੰਦ ਨਾਲ ਖਾਓ ਅਤੇ ਪੀਓ।" 52:19; 77:43
- = ਜਾਂ ਤੁਸੀਂ ਉਹਨਾਂ ਤੋਂ ਕੋਈ ਬਦਲਾ ਮੰਗਦੇ ਹੋ, ਇਸ ਲਈ ਉਹ ਕਰਜ਼ੇ ਦੇ ਬੋਝ ਹੇਠ ਦੱਬੇ ਹੋਏ ਹਨ? 52:40; 68:46
- = ਜਾਂ ਉਹਨਾਂ ਕੋਲ ਗੁਪਤ ਗਿਆਨ ਹੈ, ਇਸ ਲਈ ਉਹ (ਉਸ ਨੂੰ) ਲਿਖ ਰਹੇ ਹਨ? 52:41; 68:47
- = ਤਾਂ ਮੇਰੀ ਸਜਾ ਅਤੇ ਮੇਰੀ ਡਰਾਵਣੀ ਕਿਵੇਂ (ਸਖ਼ਤ) ਸੀ! 54:16; 54:21; 54:30
- = ਅਤੇ ਅਸੀਂ ਕੁਰਆਨ ਨੂੰ ਯਾਦ ਰੱਖਣ ਲਈ ਸੌਖਾ ਕਰ ਦਿੱਤਾ ਹੈ। ਤਾਂ ਕੋਈ ਹੈ ਜੋ ਯਾਦ ਰੱਖੇ? 54:17; 54:22; 54:32; 54:40
- = ਤਾਂ ਤੁਸੀਂ ਆਪਣੇ ਰੱਬ ਦੀਆਂ ਕਿਹੜੀਆਂ ਨੇ'ਮਤਾਂ ਦਾ ਇਨਕਾਰ ਕਰੋਗੇ? 55:13; 55:16; 55:18; 55:21; 55:23; 55:25; 55:28; 55:30; 55:32; 55:34; 55:36; 55:38; 55:40; 55:42; 55:45; 55:47; 55:49; 55:51; 55:53; 55:55; 55:57; 55:59; 55:61; 55:63; 55:65; 55:67; 55:69; 55:71; 55:73; 55:75; 55:77
- = ਪਹਿਲਿਆਂ ਵਿੱਚੋਂ ਇੱਕ ਵੱਡਾ ਗਰੋਹ। 56:13; 56:39
- = ਅਤੇ ਅਸੀਂ (ਫ਼ਸਲ ਤੋਂ) ਵਾਂਝੇ ਰਹਿ ਗਏ? 56:67; 68:27
- = ਤਾਂ ਆਪਣੇ ਮਹਾਨ ਰੱਬ ਦੇ ਨਾਮ ਦੀ ਤਸਬੀਹ ਕਰੋ। 56:74; 56:96; 69:52
- = ਇਹ ਸਾਰੇ ਸੰਸਾਰ ਦੇ ਰੱਬ ਵੱਲੋਂ ਉਤਾਰਿਆ ਗਿਆ ਹੈ। 56:80; 69:43
- = ਜੋ ਕੁਝ ਅਸਮਾਨਾਂ ਵਿੱਚ ਹੈ ਅਤੇ ਜੋ ਕੁਝ ਧਰਤੀ ਵਿੱਚ ਹੈ, ਸਭ ਅੱਲਾਹ ਦੀ ਤਸਬੀਹ ਕਰਦਾ ਹੈ, ਅਤੇ ਉਹੀ ਉੱਤਮ ਸ਼ਕਤੀ ਵਾਲਾ, ਬੜੀ ਹਿਕਮਤ ਵਾਲਾ ਹੈ। 59:1; 61:1
- = ਜਦੋਂ ਉਸ ਨੂੰ ਸਾਡੀਆਂ ਆਇਤਾਂ ਸੁਣਾਈਆਂ ਜਾਂਦੀਆਂ ਹਨ, ਤਾਂ ਉਹ ਆਖਦਾ ਹੈ: "ਇਹ ਤਾਂ ਪੁਰਾਣਿਆਂ ਦੀਆਂ ਕਹਾਣੀਆਂ ਹਨ!" 68:15; 83:13
- = ਤਾਂ ਉਹ ਸੁਖਦ ਜੀਵਨ ਵਿੱਚ ਹੋਵੇਗਾ। 69:21; 101:7
- = ਉੱਚੇ ਬਾਗ ਵਿੱਚ। 69:22; 88:10
- = ਅਤੇ ਉਹ ਮਿਸਕੀਨਾਂ ਨੂੰ ਖੁਆਉਣ ਦੀ ਤਰਗੀਬ ਨਹੀਂ ਦਿੰਦਾ। 69:34; 107:3
- = ਨਿਸ਼ਚੇ ਹੀ ਇਹ (ਕੁਰਆਨ) ਇੱਕ ਮਾਣਯੋਗ ਰਸੂਲ (ਜਿਬਰੀਲ) ਦਾ ਕਥਨ ਹੈ। 69:40; 81:19
- = ਨਿਸ਼ਚੇ ਹੀ ਇਹ ਇੱਕ ਉਪਦੇਸ਼ ਹੈ; ਜਿਹੜਾ ਚਾਹੇ, ਉਹ ਆਪਣੇ ਰੱਬ ਵੱਲ ਰਾਹ ਬਣਾ ਲਵੇ। 73:19; 76:29
- = ਤਾਂ ਜਿਹੜਾ ਚਾਹੇ, ਉਹ ਇਸ ਨੂੰ ਯਾਦ ਰੱਖੇ। 74:55; 80:12
- = ਉਸ ਦਿਨ ਝੁਠਲਾਉਣ ਵਾਲਿਆਂ ਲਈ ਤਬਾਹੀ ਹੈ! 77:15; 77:19; 77:24; 77:28; 77:34; 77:37; 77:40; 77:45; 77:47; 77:49; 83:10
- = ਨਿਸ਼ਚੇ ਹੀ ਪੁੰਨਵਾਨ ਲੋਕ ਸੁਖ-ਸ਼ਾਂਤੀ ਵਿੱਚ ਹੋਣਗੇ। 82:13; 83:22
- = ਇਹ ਇੱਕ ਲਿਖੀ ਹੋਈ ਦਸਤਾਵੇਜ਼ ਹੈ। 83:9; 83:20
- = ਉੱਚੀਆਂ ਗੱਦੀਆਂ 'ਤੇ (ਬੈਠੇ) ਦੇਖ ਰਹੇ ਹੋਣਗੇ। 83:23; 83:35
- = ਅਤੇ ਆਪਣੇ ਰੱਬ ਦਾ ਹੁਕਮ ਮੰਨਿਆ, ਅਤੇ ਉਸ ਨੂੰ ਇਸੇ ਤਰ੍ਹਾਂ ਕਰਨਾ ਚਾਹੀਦਾ ਸੀ। 84:2; 84:5
- = ਅਤੇ ਨਾ ਮੈਂ ਉਸ ਦੀ ਪੂਜਾ ਕਰਦਾ ਹਾਂ ਜਿਸ ਦੀ ਤੁਸੀਂ ਪੂਜਾ ਕਰਦੇ ਹੋ। 109:3; 109:5
